function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
  return {
    ...base,
    service: k,
    planId: k === "vps" ? rec?.id ?? null : null,
    region: cat.regions[0]?.key ?? null,
    /* Must be a PLAIN_OS. Taking `oses[0]` picked whatever sorted first, and
       once the real catalogue landed that was Docker — an APPLICATION — so a
       fresh order defaulted to "operating system: Docker".
       Prefer the newest Ubuntu specifically — the most recognisable, most
       requested default — over whichever PLAIN_OS row happens to sort
       first alphabetically (AlmaLinux, before this). Falls back to the old
       "first PLAIN_OS" behavior if Ubuntu isn't in the catalogue at all. */
    osId: (
      cat.oses
        .filter((x) => x.category === "PLAIN_OS" && x.family === "ubuntu")
        .sort((a, b) => parseFloat(b.version || "0") - parseFloat(a.version || "0"))[0]
      ?? cat.oses.find((x) => x.category === "PLAIN_OS")
      ?? cat.oses[0]
    )?.id ?? null,
    termMonths: 1,
    hostname: k === "vps" ? "web-01" : "",
    serverName: k === "game" ? "My server" : "",
    addons: [],   // nothing that costs money is pre-selected
    diskGb: 0,
    /* A game order starts with NO family chosen — the picker is the next step,
       and pre-selecting one would put a product in the cart nobody asked for. */
    gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "",
    /* Hosting and email are bought against a DOMAIN, which only the customer
       can supply — there is no sensible default, so the field starts empty
       and the step is not "done" until they type one. */
    domain: "",
    subdomainLabel: "",
    /* Both seed their cheapest plan so the order is immediately priceable. */
    hostingPlanId: k === "hosting" ? (cat.hosting[0]?.id ?? null) : null,
    emailPlanId: k === "email" ? (cat.email[0]?.id ?? null) : null,
  };
